/// <summary>
/// Controller class for managing the transfer load planning report generation process.
/// </summary>
public class METTransferLoadPlanningController extends SrsReportRunController
{
    METTransferOrderExtractScreenTmp        tempTable;
    CreatedTransactionId                    createdTransactionId;

}

Method.Source:
/// <summary>
/// Entry point for the transfer load planning report controller.
/// Initializes the controller, processes arguments, and handles cleanup if the dialog is cancelled.
/// </summary>
/// <param name="_args">Arguments containing report parameters and context.</param>
public static void main(Args _args)
{
    METTransferLoadPlanningController           controller = new METTransferLoadPlanningController();
    METLoadPlanningReport                       loadPlanningReport = _args.parmEnum();
    controller.parmArgs(_args);
    controller.parmShowDialog(false);

    controller.initFromArgs(_args);
    controller.startOperation();

    if (controller.isDialogCancelled())
    {
        if (loadPlanningReport == METLoadPlanningReport::LoadPlanningReport)
        {
            METTransferOrderLoadPlanningLinesTmp transferOrderLoadPlanningLinesTmp;

            delete_from transferOrderLoadPlanningLinesTmp
                where transferOrderLoadPlanningLinesTmp.CreatedTransactionId == controller.createdTransactionId;
        }
        else
        {
            METTransferOrderLoadPlanningAidLinesTmp transferOrderLoadPlanningAidLinesTmp;

            delete_from transferOrderLoadPlanningAidLinesTmp
                where transferOrderLoadPlanningAidLinesTmp.CreatedTransactionId == controller.createdTransactionId;
        }
    }
}

/// <summary>
/// Indicates whether the report dialog was cancelled by the user.
/// </summary>
/// <returns>True if the dialog was cancelled; otherwise, false.</returns>
public boolean isDialogCancelled()
{
    return dialogCanceled;
}

/// <summary>
/// Creates the report data based on the provided arguments and selected records.
/// </summary>
/// <param name="_args">Arguments containing the selected records and report type.</param>
public void createReportData(Args _args)
{
    FormRun         formRun;
    METLoadPlanningReport   loadPlanningReport = _args.parmEnum();

    tempTable.linkPhysicalTableInstance(_args.record() as METTransferOrderExtractScreenTmp);

    if (_args.caller())
    {
        formRun = _args.caller();
        Map             map = formRun.getSelectedRecordsMap();

        if (loadPlanningReport == METLoadPlanningReport::LoadPlanningReport)
        {
            createdTransactionId = METLoadPlanningReportHelper::setTOReportLoadPlanningTmp(map, tempTable);
        }
        else
        {
            createdTransactionId = METLoadPlanningReportHelper::setTOReportLoadPlanningAIDTmp(map, tempTable);
        }
    }
}

/// <summary>
/// Initializes the controller from the provided arguments and sets the report name.
/// </summary>
/// <param name="_args">Arguments containing the report type and context.</param>
public void initFromArgs(Args _args)
{
    METLoadPlanningReport loadPlanningReport = _args.parmEnum();

    switch (loadPlanningReport)
    {
        case METLoadPlanningReport::LoadPlanningAidReport:
            this.parmReportName(ssrsReportStr(METTransferOrderLoadPlanningAidReport, Report));
            break;

        case METLoadPlanningReport::LoadPlanningReport:
            this.parmReportName(ssrsReportStr(METTransferOrderLoadPlanningReport, Report));
            break;
    }

    this.createReportData(_args);
}

/// <summary>
/// Modifies the report contract before running the report, setting the transaction ID.
/// </summary>
protected void preRunModifyContract()
{
    METTransferOrderLoadPlanningContract contract = this.parmReportContract().parmRdpContract() as METTransferOrderLoadPlanningContract;

    new SRSReportRunPermission().assert();

    contract.parmTransaction(createdTransactionId);
}
